//! A catalogue's messages as TypeScript: the global `LxAppMessages` interface, one property per
//! key whose type is the arguments the message takes, so `t` checks a key and its arguments.

use crate::catalogue::Catalogue;
use crate::message::Use;

pub fn declarations(catalogue: &Catalogue) -> String {
    let mut out = String::from(
        "// Generated by the lingxia CLI from this lxapp's source catalogue. Do not edit.\n\n\
         interface LxAppMessages {\n",
    );
    for (key, entry) in &catalogue.entries {
        if let Some(description) = &entry.description {
            out.push_str(&format!("  /** {} */\n", description.replace("*/", "*\\/")));
        }
        let args: Vec<String> = entry
            .signature
            .iter()
            .map(|(name, use_)| match use_ {
                Use::Tag => format!(
                    "{:?}: (contents: any) => unknown",
                    name.trim_start_matches('<').trim_end_matches('>')
                ),
                _ => format!("{name:?}: {}", ts(use_)),
            })
            .collect();
        if args.is_empty() {
            out.push_str(&format!("  {key:?}: Record<string, never>;\n"));
        } else {
            out.push_str(&format!("  {key:?}: {{ {} }};\n", args.join("; ")));
        }
    }
    out.push_str("}\n");
    out
}

fn ts(use_: &Use) -> String {
    match use_ {
        Use::Text => "string | number".into(),
        Use::Number => "number".into(),
        Use::Date => "number | Date".into(),
        // `other` takes any value; the named cases are what an editor offers.
        Use::Select(keys) => keys
            .iter()
            .map(|key| format!("{key:?}"))
            .chain(["(string & {})".into()])
            .collect::<Vec<_>>()
            .join(" | "),
        Use::Tag => unreachable!(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn each_key_takes_the_arguments_its_message_uses() {
        let catalogue = Catalogue::parse(
            r#"{
              "cart.items": { "defaultMessage": "{count, plural, one {# item} other {# items}} by {when, date, short}", "description": "Under the list." },
              "cart.state": { "defaultMessage": "{state, select, open {Open} other {Closed}}", "description": "Badge." },
              "cart.terms": { "defaultMessage": "Accept the <link>terms</link>, {name}.", "description": "Footer." }
            }"#,
            true,
        )
        .unwrap();
        let dts = declarations(&catalogue);
        assert!(dts.contains("  /** Under the list. */\n  \"cart.items\": { \"count\": number; \"when\": number | Date };\n"), "{dts}");
        assert!(
            dts.contains("\"cart.state\": { \"state\": \"open\" | (string & {}) };"),
            "{dts}"
        );
        assert!(dts.contains("\"cart.terms\": { \"link\": (contents: any) => unknown; \"name\": string | number };"), "{dts}");
    }
}
